public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Horizontal lines
    for (int i = 0; i < m; i++) {
        int currentLength = 0;
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                currentLength++;
            } else {
                maxLength = Math.max(maxLength, currentLength);
                currentLength = 0;
            }
        }
        maxLength = Math.max(maxLength, currentLength);
    }

    // Vertical lines
    for (int j = 0; j < n; j++) {
        int currentLength = 0;
        for (int i = 0; i < m; i++) {
            if (mat[i][j] == 1) {
                currentLength++;
            } else {
                maxLength = Math.max(maxLength, currentLength);
                currentLength = 0;
            }
        }
        maxLength = Math.max(maxLength, currentLength);
    }

    // Diagonal lines
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int currentLength = 1;
            int ii = i + 1;
            int jj = j + 1;
            while (ii < m && jj < n && mat[ii][jj] == 1) {
                currentLength++;
                ii++;
                jj++;
            }
            maxLength = Math.max(maxLength, currentLength);
        }
    }

    // Anti-diagonal lines
    for (int i = 0; i < m; i++) {
        for (int j = n - 1; j >= 0; j--) {
            int currentLength = 1;
            int ii = i + 1;
            int jj = j - 1;
            while (ii < m && jj >= 0 && mat[ii][jj] == 1) {
                currentLength++;
                ii++;
                jj--;
            }
            maxLength = Math.max(maxLength, currentLength);
        }
    }

    return maxLength;
}

