public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    int[] indices = new int[n];
    for (int i = 0; i < n; i++) {
        indices[i] = i;
    }
    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dp[i][j] = Integer.MAX_VALUE;
        }
    }
    for (int i = 0; i < n; i++) {
        dp[i][i] = 0;
    }
    for (int l = 2; l <= n; l++) {
        for (int i = 0; i + l - 1 < n; i++) {
            int j = i + l - 1;
            for (int k = i; k <= j; k++) {
                if (l % 2 == 0) {
                    dp[i][j] = Math.min(dp[i][j], dp[i][k - 1] + dp[k + 1][j]);
                } else {
                    dp[i][j] = Math.min(dp[i][j], dp[i][k - 1] + dp[k + 1][j] + 1);
                }
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) {
                continue;
            }
            if (dp[i][j] <= dp[i][j - 1]) {
                count++;
            }
        }
    }
    return count;
}

