public static int findNthUglyNumber(int n) {
    int[] ugly = new int[n];
    int nextUgly = 1;
    int index2 = 0, index3 = 0, index5 = 0;

    ugly[0] = 1;
    for (int i = 1; i < n; i++) {
        nextUgly = Math.min(2 * ugly[index2], Math.min(3 * ugly[index3], 5 * ugly[index5]));
        ugly[i] = nextUgly;

        while (ugly[index2] * 2 <= nextUgly) index2++;
        while (ugly[index3] * 3 <= nextUgly) index3++;
        while (ugly[index5] * 5 <= nextUgly) index5++;
    }

    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    int energy = 1;
    char currentChar = s.charAt(0);
    int currentCharIndex = 0;

    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == currentChar) {
            currentCharIndex = i;
        } else {
            energy = Math.max(energy, i - currentCharIndex);
            currentChar = c;
            currentCharIndex = i;
        }
    }

    energy = Math.max(energy, s.length() - currentCharIndex);
    return energy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        int num = i;
        boolean greaterTen = false;
        while (num % 10 == 0) {
            num /= 10;
            greaterTen = true;
        }
        if (greaterTen) {
            result.add(i);
        } else {
            int digit = num % 10;
            int index = digit - 1;
            while (result.size() > index && result.get(index) > digit) {
                index++;
            }
            result.add(index, digit);
        }
    }
    return result;
}

